"""Layer 15 MLP unit 704 (this component is that hidden unit, scaled by about 1).

It is a diffuse neuron. Its clearest pattern is negative values on source-code
import and package statements: the `import`/`package` keyword and the module or
package path after it. Digits are mildly negative. Most other text is near zero,
and its variance is spread across many contexts, so these rules explain only a
sliver of it.
"""

READS = ()

IMPORT_STARTS = ("import", "package", "#include", "using ")
KEYWORD_TOKENS = {"import", "package", "#include", "using"}
KEYWORD_VALUE = -2.3  # the statement keyword itself
PATH_VALUE = -0.7  # other tokens on an import or package line
DIGIT_VALUE = -0.2  # a digit token anywhere


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[1] != doc:
        line = ""
    else:
        line = carry[0]
    # the current line so far, from its last newline
    if "\n" in token:
        line = token[token.rfind("\n") + 1 :]
    else:
        line = line + token
    stripped = line.lstrip()
    in_import = stripped.startswith(IMPORT_STARTS)
    if in_import and token.strip() in KEYWORD_TOKENS:
        value = KEYWORD_VALUE
    elif in_import:
        value = PATH_VALUE
    elif token.strip().isdigit():
        value = DIGIT_VALUE
    else:
        value = 0.0
    return (line, doc), value

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:709 (Qwen3-1.7B, layer 15 MLP down_proj).

Its activation is almost entirely set by one MLP hidden unit, 709 of layer 15: its
largest input weight. That unit goes negative on words that open a complement inside
a predicate or noun phrase: articles and possessives (a, an, the, its, his, ...),
infinitive "to", "be"/"been", degree adverbs (very, more, most, highly) and -ly
adverbs. The negative value is strongest when the word follows a linking or auxiliary
verb ("is a", "as a", "has been", "need to", "is very"), weaker after a preposition
("in the") and mild elsewhere. After a subordinator ("that a", "if the") an article is
slightly positive. An adjective right after an article ("a powerful") is also
negative. Everything else predicts 0.

The values are rough class means in activation units. The program captures the sign
and rough size of the effect, not its large context-specific tails, so it explains
only a small share of the variance.
"""
import wordnet

READS = ()

DETERMINERS = {"a", "an", "the", "its", "his", "her", "their", "our", "my", "your",
               "this", "these", "those", "some", "every", "each", "la", "le", "les", "un",
               "une", "una", "el", "der", "die", "das", "ein", "eine", "zu"}
DEGREE = {"very", "more", "most", "highly", "greatly", "also", "further", "really",
          "often", "always", "much", "too", "significantly", "completely", "fully",
          "easily", "widely", "quite"}
LINKING = {"is", "was", "are", "were", "be", "been", "being", "has", "have", "had",
           "as", "become", "became", "make", "made", "need", "used", "want", "try",
           "trying", "let"}
PREPOSITIONS = {"in", "on", "with", "by", "for", "of", "at", "from", "into", "during",
                "under", "through", "to"}
SUBORDINATORS = {"that", "if", "which", "where", "how", "when", "while"}


def word(token):
    """The token as a lowercase word if it starts a word (leading space), else ''."""
    text = token.lower()
    return text.strip() if text.startswith(" ") and text.strip().isalpha() else ""


def is_modifier(w):
    """An adjective or adverb that is not also a noun (WordNet)."""
    parts = wordnet.parts_of_speech(w) if w else set()
    return bool(parts) and ("adjective" in parts or "adverb" in parts) and "noun" not in parts


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    p = word(prefix.token_strings[-2]) if same_doc else ""
    if w in DETERMINERS:
        if p in LINKING:
            value = -3.2
        elif p in PREPOSITIONS:
            value = -1.4
        elif p in SUBORDINATORS:
            value = 0.3
        else:
            value = -1.0
    elif w in {"to", "be", "been", "being"}:
        value = -2.5 if p in LINKING else -1.2
    elif w in DEGREE:
        value = -5.0 if p in LINKING else -2.5
    elif len(w) > 4 and w.endswith("ly"):
        value = -3.0 if p in LINKING else -1.5
    elif p in DETERMINERS and is_modifier(w):
        value = -1.4
    else:
        value = 0.0
    return carry, value

"""Predict layers.15.mlp.down_proj:712, a weak and diffuse MLP component.

In plain terms: the component is strongest on the words a model uses to narrate its own
reasoning: connectives that open a step ("Hmm", "Wait", "So", "Therefore", "Thus", "Hence",
"Okay", "Perfect"), and self-checking talk about the work ("carefully", "correctly",
"mistake", "approach", "method", "problem", "step"). It is raised after a paragraph break
("...\n\n"), by abstract nouns (cognition, feeling, attribute, process) and by
mid-frequency English words, and by the first use of a word in its document. It is pushed
down by hedges ("maybe", "perhaps", "since"), by a few chat/reasoning-markup words ("let",
"actually", "now", "assistant", "</think>"), and it drifts down deep into a document.

Most of its variance is not captured by any of this (a per-token table would do somewhat
better, but would not be readable). Each value is a sum of these terms, read from the
newest token and the document's earlier tokens only.
"""

import functools

import regex
import wordfreq
import wordnet

READS = ()

STEP_WORDS = {  # openers of a reasoning step
    "hmm", "wait", "so", "therefore", "thus", "hence", "however", "alternatively",
    "similarly", "okay", "alright", "sure", "perfect", "excellent", "indeed", "instead",
}
CHECK_WORDS = {  # self-checking talk about the work
    "carefully", "correctly", "mistake", "typo", "confusing", "successfully", "helpful",
    "challenge", "challenges", "insight", "insights", "approach", "method", "methods",
    "issue", "problem", "question", "questions", "solution", "answer", "step", "process",
    "again", "differently", "necessary", "correct", "way",
}
HEDGES = {"maybe", "perhaps", "since", "probably", "might", "could", "possibly"}
MARKUP_WORDS = {"let", "actually", "now", "assistant", "</think>", "<think>"}
ABSTRACT = {
    "noun.cognition", "noun.feeling", "noun.attribute", "noun.state", "noun.event",
    "noun.process", "noun.act", "noun.phenomenon", "verb.cognition", "verb.emotion",
}
BASE = -0.10  # typical value of the component
PARAGRAPH_END = 0.58  # a token that ends a paragraph: ".\n\n" and its kin
FIRST_USE = 0.12  # a word's first occurrence in its document
DEEP = 128  # positions into a document after which it drifts down
DEEP_DROP = -0.09


@functools.lru_cache(maxsize=None)
def token_value(token):
    """The token's own contribution, from its spelling and meaning."""
    word = token.strip().lower()
    value = 0.0
    if word in STEP_WORDS:
        value += 1.4
    if word in CHECK_WORDS:
        value += 0.9
    if word in HEDGES:
        value -= 0.38
    if word in MARKUP_WORDS:
        value -= 0.25
    if token.endswith(".\n\n") or token.endswith("。\n\n") or token.endswith("`\n\n"):
        value += PARAGRAPH_END
    if regex.fullmatch(r"\p{L}{2,}", word):
        if wordnet.categories(word) & ABSTRACT:
            value += 0.12
        if 4 <= wordfreq.zipf_frequency(word, "en") < 6:
            value += 0.08
    return value


def step(carry, prefix, upstream):
    """The activation at the newest token, given the document so far."""
    token = prefix.token_ids[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry["document"] != document:
        carry = {"document": document, "position": 0, "seen": set()}
    else:
        carry["position"] += 1
    value = BASE + token_value(prefix.token_strings[-1])
    if token not in carry["seen"]:
        value += FIRST_USE
    carry["seen"].add(token)
    if carry["position"] >= DEEP:
        value += DEEP_DROP
    return carry, float(value)

"""Degree and wh-words that open a phrase, with a faint lean on a few other word classes.

Component p-82af68dd@100000/layers.15.mlp.down_proj:729 is mostly quiet, with a diffuse
small value on nearly every token. Its clearest large positive activations come on the
words that open a question or a comparison: "most", "more", "how", "what", "why", "much".
Its output direction promotes words like "importance", "utility", "benefit", so it
fires where an evaluative or explanatory phrase is about to start.

The program reads the newest token and the one before it:
- a fixed value for each of those words, the average measured on training text;
- "most" and "more" right after a determiner ("the most", "a more") are much stronger;
- the idioms "at most", "more or less", "no more", "once more" are near 0;
- relative pronouns ("that", "who", "which", "where") lean slightly positive;
- commas and common prepositions ("of", "and", "to", "by", "with", "or") lean slightly negative.

Everything else is 0. The program captures only a small part of the component's variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# average activation after each word, measured on training text
VALUES = {
    "most": 1.7,
    "more": 1.1,
    "how": 1.4,
    "what": 0.8,
    "why": 1.0,
    "much": 0.4,
    "importance": 1.1,
}
DETERMINERS = {"the", "a", "an", "their", "his", "its"}
IDIOM_BEFORE = {"at", "or", "no", "once", "than"}
RELATIVES = {"that", "who", "which", "where"}
MILD_NEGATIVE = {",", "of", "and", "to", "by", "with", "or"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    if word in VALUES:
        before = ""
        if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
            before = prefix.token_strings[-2].strip().lower()
        if word in ("most", "more") and before in IDIOM_BEFORE:
            return carry, 0.0
        if word in ("most", "more") and before in DETERMINERS:
            return carry, 2.4
        return carry, VALUES[word]
    if word in RELATIVES:
        return carry, 0.15
    if word in MILD_NEGATIVE:
        return carry, -0.04
    return carry, 0.0

"""Targeting / audience detector for MLP neuron 732 of layer 15.

The neuron is mostly noise (its activation has std 0.5 and no word explains much of it),
but its positive tail sits on words that single out a specific audience or kind of
person: "attract", "niche", "demographic", "clientele", "targeting", "geared", "cater",
"seeking", "prefer", "minority", "vulnerable", "adults", "consumers", "buyers", "audience";
on the qualifiers that introduce such a subgroup ("typically", "mainly", "particularly",
"rarely"); and on "kind/type/sort of". Its negative tail sits on "language(s)", "spoken",
"written", "located". Everything else sits near its baseline of -0.05.
"""
READS = ()

STRONG = {"attract", "attracts", "attracted", "attracting", "niche", "demographic",
          "clientele", "geared", "targeting", "minority", "minorities", "vulnerable",
          "enthusiasts", "seeker", "seekers"}
MEDIUM = {"audience", "audiences", "buyers", "consumers", "customers", "adults", "teens",
          "populations", "cater", "caters", "seek", "seeks", "seeking", "sought", "prefer",
          "prefers", "preferred", "preferences", "selective", "appeal", "appealing",
          "appealed", "targeted", "target", "targets", "suited", "elderly", "youth", "women",
          "rarely", "mainly", "particularly", "typically", "primarily", "especially", "kinds"}
WEAK = {"kind", "sort", "type", "types", "people", "kids", "young", "population", "groups",
        "specific", "mostly"}
LOCATION = {"language", "languages", "spoken", "written", "located", "situated"}
KIND = {"type", "types", "kind", "kinds", "sort", "sorts"}
BASE = -0.05


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if cur in ("to", "for") and prev in STRONG | MEDIUM:
        value = 0.7
    elif cur == "of" and prev in KIND:
        value = 1.2
    elif cur in STRONG:
        value = 2.0
    elif cur in MEDIUM:
        value = 0.9
    elif cur in WEAK:
        value = 0.3
    elif cur in LOCATION:
        value = -0.8
    else:
        value = BASE
    return carry, value

"""Go-source detector for layers.15.mlp.down_proj:736.

What it does: this component writes a large positive signal into the residual stream
while the model reads Go source code, and is near zero on prose and most other text.
Within Go it is largest on the Go words that carry the language's structure: `func`,
`var`, `type` and friends, error-handling idioms (`err`, `:=`, `nil`, `return`, `fmt`),
and type names (`string`, `int`, `[]`, `*`, `&`). Punctuation and indentation are weakly
positive; ordinary identifiers and prose words are near zero.

How it is computed, token by token:
  1. Classify the newest token into a category (declaration word, idiom, type, punctuation,
     whitespace, plain word, other).
  2. Keep a count of Go marker tokens seen so far in the current document. Once there are
     at least 3, the document counts as Go; the count resets at each document boundary.
  3. Output the category's activation: a Go-context table inside Go, a weaker table elsewhere
     (declaration words and type names still fire a little in other typed code).
"""
import re

READS = ()

DECL = {"func", "var", "type", "const", "struct", "interface", "package", "import"}
IDIOM = {"err", "error", "nil", "fmt", ":=", "return", "if", "for", "range", "make", "append", "ok", "_,"}
TYPE = {"string", "int", "byte", "bool", "String", "char", "void", "float64", "int64", "any", "[]", "*", "&", "(*", "(&"}
# Tokens that mark a document as Go once several of them have appeared.
GO_MARKERS = {"func", ":=", "err", "nil", "return", "package", "fmt", "import"}
# Mean activation per category inside Go (>= 3 markers so far) and elsewhere.
IN_GO = {"decl": 7.5, "idiom": 9.6, "type": 7.7, "punct": 1.3, "space": 0.5, "ws": 1.4, "word": 0.6, "other": 0.7}
ELSEWHERE = {"decl": 3.9, "idiom": 0.6, "type": 2.1, "punct": 0.1, "space": 0.1, "ws": 0.1, "word": 0.1, "other": 0.1}


def category(raw):
    word = raw.strip(" \t\r\n")
    if not word:
        return "ws" if ("\t" in raw or "\n" in raw) else "space"
    if word in DECL:
        return "decl"
    if word in IDIOM:
        return "idiom"
    if word in TYPE:
        return "type"
    if re.fullmatch(r"[^\w\s]+", word):
        return "punct"
    if re.fullmatch(r"[A-Za-z_]\w*", word):
        return "word"
    return "other"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    seen = carry[1] if carry is not None and carry[0] == doc else 0
    raw = prefix.token_strings[-1]
    if raw.strip(" \t\r\n") in GO_MARKERS:
        seen += 1
    table = IN_GO if seen >= 3 else ELSEWHERE
    return (doc, seen), table[category(raw)]

"""Layer 15 MLP down-projection, component 738: a code-conditional detector.

In plain terms: this component is pushed up when the model is reading a test in code. Its
strongest response is the word "if" (or "elif"/"while") that opens a line, the start of a
conditional statement. It also responds, more weakly, to null checks (null, None, undefined,
nil) and to comparison operators (!=, ==, ===, !==, ≠), and it is pushed slightly down by
error-handling words (err, error, throw, exception). Everywhere else it sits at a tiny negative level.

The program reads only the current token and the one before it, so it has no state.
"""

from collections.abc import Mapping

READS = ()

COND_WORDS = {"if", "elif", "while"}
NULL_WORDS = {"null", "none", "nil", "nullptr", "undefined", "empty"}
NULL_AFTER = {"!=", "!==", "==", "===", "≠", "=", "return", "?", "is"}
COMPARE_OPS = {"!=", "!==", "==", "===", "≠", "(!"}
ERROR_WORDS = {"err", "error", "throw", "throws", "exception", "raise"}


def step(carry, prefix, upstream: Mapping):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else ""
    before = previous.strip()
    # "if" opens a line: after indentation or a newline, or carrying its own tab or newline
    line_start = before == "" or "\n" in previous or raw[:1] in ("\t", "\n")
    if word in COND_WORDS:
        value = 2.0 if line_start else 0.2
    elif word in NULL_WORDS:
        value = 1.0 if before in NULL_AFTER else 0.6
    elif word in COMPARE_OPS:
        value = 0.5
    elif word in ERROR_WORDS:
        value = -0.45
    else:
        value = -0.03
    return carry, value

"""Layer 15 MLP down_proj, component 740: a weak feature whose main variance is not explained.

What it does: the component's activation is roughly unit-scale noise (std ~1) across
ordinary text. Its size is spread over about 6000 MLP hidden units (the ten largest carry
about 7% of its variance), so no token or surface property predicts most of it. The part
that can be read off the text is a sparse set of mean offsets, measured on training rows:

  - NUL characters: mean about -2.9 (strongly negative);
  - truncation markers, "..." and "…" (and tokens like " ...\\n"): mean about -0.8, often
    much more negative where a snippet is cut off mid-sentence;
  - runs of four or more spaces (indentation, column-aligned listings): mean about -0.4;
  - the end-of-turn token "<|im_end|>": mean about +1.3.

Every other token gets 0, the average over ordinary text. The program is stateless: it
reads only the newest token of the prefix.
"""

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if "\x00" in tok:
        value = -2.9
    elif "..." in tok or "…" in tok:
        value = -0.8
    elif len(tok) >= 4 and tok.strip() == "":
        value = -0.4
    elif tok == "<|im_end|>":
        value = 1.3
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP neuron 759, the component p-82af68dd@100000/layers.15.mlp.down_proj:759, as word rules.

This component is one hidden unit of the layer-15 MLP: its read direction is almost
entirely that unit (weight 0.95 on it, about 0.05 on any other), so its activation is that
unit's value, scaled. The unit is high on the word just before a verb of opinion, evaluation
or citation, in hedged phrases, and on such verbs themselves:

    "it is important [to] note"      "we should also [mention]"     "let [me] think"
    "can [be] compared"  "[considered]"  "is worth [noting]"  "let['s] consider"

It is low in noun-and-auxiliary slots, where the next word is "of", "to" or "is":
"our [goal] is", "the [purpose] of", "what [would] you".

The program scores each word from the word itself and the word before it, with a few
hand-set weights. It explains only a few percent of the variance (about 3 to 4 percent):
most of the activation lies in ordinary words and in context these word rules do not see.
"""

READS = ()

MODALS = {"can", "could", "should", "may", "might", "must", "will", "would", "shall", "cannot"}
SUBJECT_PRONOUNS = {"we", "i", "you", "one", "they", "it", "let"}
ADVERBS_BEFORE_BE = {"also", "never", "always", "even", "still", "please", "not", "just"}
BE_FORMS = {"be", "is", "are", "been", "being", "was", "were"}

# adjectives and verbs that set up an infinitive: "important to", "hard to", "like to"
EVAL_ADJECTIVES = {
    "important", "interesting", "difficult", "hard", "impossible", "necessary", "possible",
    "worth", "easy", "useful", "pleased", "like", "ought", "likely", "unlikely", "best",
    "referred", "easier", "harder", "good", "crucial",
}
# verbs of thinking, saying, noting and evaluating
OPINION_VERBS = {
    "think", "say", "consider", "note", "mention", "remember", "assume", "recommend", "imagine",
    "believe", "know", "regard", "view", "compare", "point", "recognize", "accept", "agree",
    "suppose", "understand", "thank", "known", "considered", "referred", "classified",
    "understood", "refer", "describe", "check", "verify", "predict", "judge",
}
# past participles of such verbs, as in "can be compared", "is known", "was said"
PASSIVE_VERBS = {
    "considered", "compared", "said", "regarded", "attributed", "noted", "interpreted", "taken",
    "traced", "stated", "understood", "known", "seen", "viewed", "described", "defined", "cited",
    "assumed", "expected", "read", "construed", "mentioned", "referred", "called", "discussed",
}
# nouns of purpose and need, which come before "is", "of" or "to"
PURPOSE_NOUNS = {
    "goal", "purpose", "aim", "way", "need", "ability", "opportunity", "help", "desire",
    "possibility", "manner", "future",
}
AUXILIARIES = {"is", "are", "was", "were", "do", "did", "will"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    """The activation at this position, from the newest word and the one before it."""
    tokens = prefix.token_strings
    w = word(tokens[-1])
    same_doc = len(prefix.document_ids) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]
    p = word(tokens[-2]) if len(tokens) >= 2 and same_doc else ""

    score = 0.03
    if w == "to":
        score += 2.5 if p in EVAL_ADJECTIVES else 0.25
    if w == "be" and (p in MODALS or p in ADVERBS_BEFORE_BE):
        score += 0.5
    if w in MODALS and p in SUBJECT_PRONOUNS:
        score += 1.2
    if w == "me" and p == "let":
        score += 2.9
    if w in ("'s", "’s") and p == "let":
        score += 2.5
    if w in OPINION_VERBS:
        score += 1.6
    if w in PASSIVE_VERBS and p in BE_FORMS:
        score += 3.0
    if w in MODALS:
        score += 0.1
    if p in MODALS:
        score += 0.6
    if w in PURPOSE_NOUNS:
        score -= 0.5
    if w in AUXILIARIES:
        score -= 0.1
    return carry, float(score)
